'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
const $=s=>document.querySelector(s),W=window.innerWidth<650?600:1000,H=360,ground=300;
canvas.width=W;
let mode='ready',time=0,score=0,best=0,speed=310,spawn=1.6,obstacles=[],particles=[],duck=false,muted=true,audio,previous=0,runId=0;
try{best=Number(localStorage.getItem('dino-run-best'))||0}catch{}
const dino={x:100,y:ground,vy:0,w:40,h:48};
const digits=n=>String(Math.floor(n)).padStart(5,'0');$('#best').textContent=digits(best);
function tone(freq,duration=.07){if(muted)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='square';o.frequency.value=freq;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}catch{}}
function begin(){runId++;mode='running';time=0;score=0;speed=310;spawn=1.5;obstacles=[];particles=[];duck=false;dino.y=ground;dino.vy=0;$('#overlay').classList.add('hidden');$('#pause').disabled=false;$('#pause').textContent='Ⅱ PAUSE';$('#state').textContent='KEEP ON RUNNING';$('#announcement').textContent='Run started';updateHud()}
function jump(){if(mode==='ready'||mode==='over'){begin();return}if(mode==='paused')return;if(dino.y>=ground-.1){dino.vy=-650;tone(430)}}
function pause(){if(!['running','paused'].includes(mode))return;mode=mode==='running'?'paused':'running';$('#pause').textContent=mode==='paused'?'▶ RESUME':'Ⅱ PAUSE';$('#state').textContent=mode==='paused'?'TAKE A BREATHER':'KEEP ON RUNNING';if(mode==='paused'){showOverlay('A LITTLE BREATHER','Paused.','Your desert will be right here.','Resume running');}else $('#overlay').classList.add('hidden')}
function showOverlay(label,title,copy,button){$('#overlay-label').textContent=label;$('#overlay-title').textContent=title;$('#overlay-copy').textContent=copy;$('#start').innerHTML=button+' <span>↗</span>';$('#overlay').classList.remove('hidden')}
function end(){mode='over';tone(100,.25);if(score>best){best=Math.floor(score);try{localStorage.setItem('dino-run-best',best)}catch{}}updateHud();$('#pause').disabled=true;$('#state').textContent='THERE’S ALWAYS ANOTHER RUN';showOverlay('GOOD RUN, LITTLE DINO.','One more try?',`You scored ${Math.floor(score)}. The desert isn’t going anywhere.`,'Run again');$('#announcement').textContent=`Game over. Score ${Math.floor(score)}`}
function updateHud(){$('#score').textContent=digits(score);$('#best').textContent=digits(best);$('#distance').textContent=Math.floor(score*2)+' m traveled'}
function rect(x,y,w,h,color='#425b40'){ctx.fillStyle=color;ctx.fillRect(Math.round(x),Math.round(y),w,h)}
function drawDino(){const crouch=duck&&dino.y===ground;const x=dino.x,y=dino.y;ctx.save();ctx.translate(x,y);ctx.fillStyle='#344e37';if(crouch){rect(0,-24,46,16);rect(35,-31,23,17);rect(-8,-30,10,12);rect(4,-8,7,8);rect(29,-8,7,8);rect(50,-28,3,3,'#efefe5')}else{rect(8,-30,22,24);rect(24,-49,25,22);rect(20,-43,9,23);rect(3,-26,10,14);rect(-4,-34,8,18);rect(30,-24,10,5);rect(37,-21,4,7);rect(41,-44,3,3,'#efefe5');rect(37,-30,12,3,'#efefe5');const step=mode==='running'&&dino.y===ground?Math.floor(time*13)%2:0;rect(9,-8,6,step?5:8);rect(22,-8,6,step?8:5);rect(9,step?-5:-3,10,3);rect(22,step?-3:-5,10,3)}ctx.restore()}
function cactus(o){rect(o.x+o.w*.4,ground-o.h,o.w*.25,o.h);rect(o.x,ground-o.h*.72,o.w*.2,o.h*.4);rect(o.x,ground-o.h*.4,o.w*.5,7);rect(o.x+o.w*.8,ground-o.h*.85,o.w*.2,o.h*.5);rect(o.x+o.w*.6,ground-o.h*.45,o.w*.4,7)}
function draw(){ctx.clearRect(0,0,W,H);ctx.fillStyle='#efefe5';ctx.fillRect(0,0,W,H);ctx.strokeStyle='#d3d8c6';ctx.lineWidth=1;ctx.beginPath();ctx.arc(828,65,25,0,Math.PI*2);ctx.stroke();for(let i=0;i<4;i++){let x=((i*317-time*12)%1200+1200)%1200-100;ctx.fillStyle='#e0e4d6';ctx.beginPath();ctx.roundRect(x,65+i%2*38,72,5,3);ctx.fill();ctx.fillRect(x+23,58+i%2*38,30,7)}ctx.strokeStyle='#dce0d0';ctx.beginPath();ctx.moveTo(0,ground);for(let x=0;x<=W;x+=10)ctx.lineTo(x,ground-15-Math.sin((x+time*15)*.009)*13-Math.cos(x*.025)*6);ctx.stroke();rect(0,ground,W,1,'#9ba88a');for(let i=0;i<45;i++){const x=((i*47-time*speed)%1100+1100)%1100;rect(x,ground+8+i%4*9,i%3*3+2,1,'#c2cbb3')}for(const o of obstacles){if(o.type==='bird'){const y=o.y,flap=Math.sin(time*18)>0;rect(o.x+8,y+7,28,10);rect(o.x,y+10,12,5);rect(o.x+19,y+(flap?-6:15),9,14)}else cactus(o)}drawDino();if(mode==='paused'){ctx.fillStyle='#efefe5aa';ctx.fillRect(0,0,W,H)}}
function update(dt){time+=dt;score+=dt*10;speed=Math.min(650,310+score*.35);dino.vy+=(duck?2600:1850)*dt;dino.y=Math.min(ground,dino.y+dino.vy*dt);if(dino.y===ground)dino.vy=0;spawn-=dt;if(spawn<=0){const bird=score>180&&Math.random()<.25;obstacles.push(bird?{type:'bird',x:W+30,y:ground-65,w:38,h:20}:{type:'cactus',x:W+30,w:25+Math.random()*15,h:35+Math.random()*22});spawn=(.95+Math.random()*.65)*310/speed+.42}for(const o of obstacles){o.x-=speed*dt;const crouch=duck&&dino.y===ground;const a={x:dino.x+5,y:dino.y-(crouch?28:45),w:crouch?46:32,h:crouch?25:42},b={x:o.x+4,y:o.type==='bird'?o.y+5:ground-o.h+3,w:o.w-8,h:o.type==='bird'?15:o.h-3};if(a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y){end();break}}obstacles=obstacles.filter(o=>o.x+o.w>-50);updateHud()}
function frame(now){const dt=Math.min((now-previous)/1000||0,.033);previous=now;if(mode==='running')update(dt);draw();requestAnimationFrame(frame)}
$('#start').onclick=()=>mode==='paused'?pause():begin();$('#pause').onclick=pause;$('#sound').onclick=()=>{muted=!muted;$('#sound').textContent=muted?'SOUND OFF':'SOUND ON';$('#sound').setAttribute('aria-label',muted?'Enable sound':'Mute sound');tone(600)};
canvas.addEventListener('pointerdown',e=>{e.preventDefault();jump()});$('#jump').addEventListener('pointerdown',e=>{e.preventDefault();jump()});$('#duck').addEventListener('pointerdown',e=>{e.preventDefault();duck=true;e.currentTarget.setPointerCapture(e.pointerId)});for(const event of ['pointerup','pointercancel'])$('#duck').addEventListener(event,()=>duck=false);
document.addEventListener('keydown',e=>{if(e.target.closest('button,a')&&e.code==='Space')return;if(['Space','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Space'||e.code==='ArrowUp')jump();if(e.code==='ArrowDown')duck=true;if(e.code==='KeyP'||e.code==='Escape')pause()});document.addEventListener('keyup',e=>{if(e.code==='ArrowDown')duck=false});window.addEventListener('blur',()=>{duck=false;if(mode==='running')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode==='running')pause()});requestAnimationFrame(frame);
